from fractions import Fraction
from math import factorial

def legendre(m, p):
    s = 0
    while m:
        m //= p
        s += m
    return s

primes = [p for p in range(2, 101) if all(p % q for q in range(2, int(p**0.5) + 1))]

def is_int_legendre(n):
    # Only primes <= n appear in the denominator (n!)^(n+2)
    for p in primes:
        if p > n:
            break
        if legendre(n * n + 1, p) < (n + 2) * legendre(n, p):
            return False
    return True

ints = [n for n in range(1, 101) if is_int_legendre(n)]
